func TypeTransformation_clinit() {
	if TypeTransformation_clinit_done {
		return
	}
	TypeTransformation_clinit_done = true
	TypeTransformation_UNKNOWN_TYPEVAR = DiagnosticType_warning("TYPEVAR_UNDEFINED", "Reference to an unknown type variable {0}")
	TypeTransformation_UNKNOWN_STRVAR = DiagnosticType_warning("UNKNOWN_STRVAR", "Reference to an unknown string variable {0}")
	TypeTransformation_UNKNOWN_TYPENAME = DiagnosticType_warning("TYPENAME_UNDEFINED", "Reference to an unknown type name {0}")
	TypeTransformation_BASETYPE_INVALID = DiagnosticType_warning("BASETYPE_INVALID", "The type {0} cannot be templatized")
	TypeTransformation_TEMPTYPE_INVALID = DiagnosticType_warning("TEMPTYPE_INVALID", "Expected templatized type in {0} found {1}")
	TypeTransformation_INDEX_OUTOFBOUNDS = DiagnosticType_warning("INDEX_OUTOFBOUNDS", "Index out of bounds in templateTypeOf: expected a number less than {0}, found {1}")
	TypeTransformation_DUPLICATE_VARIABLE = DiagnosticType_warning("DUPLICATE_VARIABLE", "The variable {0} is already defined")
	TypeTransformation_UNKNOWN_NAMEVAR = DiagnosticType_warning("UNKNOWN_NAMEVAR", "Reference to an unknown name variable {0}")
	TypeTransformation_RECTYPE_INVALID = DiagnosticType_warning("RECTYPE_INVALID", "The first parameter of a maprecord must be a record type, found {0}")
	TypeTransformation_MAPRECORD_BODY_INVALID = DiagnosticType_warning("MAPRECORD_BODY_INVALID", "The body of a maprecord function must evaluate to a record type or a no type, found {0}")
	TypeTransformation_VAR_UNDEFINED = DiagnosticType_warning("VAR_UNDEFINED", "Variable {0} is undefined in the scope")
	TypeTransformation_INVALID_CTOR = DiagnosticType_warning("INVALID_CTOR", "Expected a constructor type, found {0}")
	TypeTransformation_RECPARAM_INVALID = DiagnosticType_warning("RECPARAM_INVALID", "Expected a record type, found {0}")
	TypeTransformation_PROPTYPE_INVALID = DiagnosticType_warning("PROPTYPE_INVALID", "Expected object type, found {0}")

}

